def test_select_cheapest_uses_first_service_on_tie():
    from shipping import select_cheapest
    parcel = {"id": "X", "weight_kg": "10", "length_cm": "1", "width_cm": "1", "height_cm": "1", "zone": "urban"}
    assert select_cheapest(parcel) == {"id": "X", "status": "selected", "service": "Express", "days": 2, "cost": 10.0}


def test_select_all_keeps_order_and_reports_unavailable():
    from shipping import select_all
    result = select_all(load())["parcels"]
    assert [entry["id"] for entry in result] == ["P1", "P2", "P3"]
    assert result[1]["service"] == "Economy"
    assert result[2]["status"] == "unavailable" and result[2]["reason"]
